import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomSwitch,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import employeesApi from "../../../api/employees/employeesApi";
import { Modal } from "antd";
import productsApi from "../../../api/productsApi";
import advertsApi from "../../../api/employees/advertsApi";
import departmentsApi from "../../../api/departmentsApi";
import designationsApi from "../../../api/employees/designationsApi";
import rolesApi from "../../../api/rolesApi";
import entitiesApi from "../../../api/entitiesApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import dayjs from "dayjs";
import usersApi from "../../../api/usersApi";

export default function EmployeesFormModal({
  openEditModal,
  setopenEditModal,
  employee,
  modalTitle = "Add new out of stock item",
  updated,
  setUpdated,
  user,
}) {


  const [crew, setCrew] = useState(
    employee && employee.crew_array
      ? employee.crew_array.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      : []
  );

  const { dangerColor, currentColor,loggedInUser } = useStateContext();

  const employeesActionsApi = useApi(employeesApi.employeesActionAdmin);
  const getEntityEmployees = async () => {
    await employeesActionsApi.request({
      action: "RetrieveEntityEmployees",
    });
  };

  useEffect(() => {
    getEntityEmployees();
  }, []);

  useEffect(() => {
    if (employeesActionsApi.data && employeesActionsApi.data.length) {
      setCrew(
        employeesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("countriesActionsApi.data", employeesActionsApi.data);
  }, [employeesActionsApi.data]);
  const moment = require("moment");

  const [errors, setErrors] = useState();

  useEffect(() => {}, [employee]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleEmployeesAction = async (data) => {
    await employeesActionsApi.request(data);

    // if (result.ok) {
    //   setopenEditModal(false);
    //   setUpdated(true);
    // } else if (result.data.errors) {
    //   setErrors(result.data.errors);
    // }

    // console.log("result at employee actions", result);
  };

  useEffect(() => {
    if (employeesActionsApi.data && employeesActionsApi.data.employee) {
      toast.success(employeesActionsApi.data.response_message);
      setopenEditModal(false);
    }

    if (
      employeesActionsApi.data &&
      employeesActionsApi.data.errors &&
      employeesActionsApi.data.errors.length
    ) {
      setErrors(employeesActionsApi.data.errors);
    }
  }, [employeesActionsApi.data]);

  const formik = useFormik({
    initialValues: {
      hire_date:
        employee && employee.hire_date
          ? employee.hire_date
          : dayjs().format("YYYY-MM-DD"),

      terminal_date:
        employee && employee.terminal_date
          ? employee.terminal_date
          : dayjs().format("YYYY-MM-DD"),
      user: employee ? { label: employee.title, value: employee.user } : null,
      department:
        employee && employee.department_title && employee.department
          ? { label: employee.department_title, value: employee.department }
          : null,
      designation:
        employee && employee.designation_title && employee.designation
          ? { label: employee.designation_title, value: employee.designation }
          : null,
      advert:
        employee && employee.advert && employee.advert_title
          ? { label: employee.advert_title, value: employee.advert }
          : null,
      basic_salary: employee ? employee.basic_salary : null,
      house_allowance: employee ? employee.house_allowance : null,
      other_allowance: employee ? employee.other_allowance : null,
      is_active: employee && employee.is_active ? employee.is_active : "false",
      roles: employee
        ? employee.roles.map((i) => ({ label: i.title, value: i.id }))
        : [],
    },

    validationSchema: Yup.object({
      hire_date: Yup.string().required().label("Hire date"),
      user: Yup.object().required().label("User"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      let arr = [];
      if (values.roles && values.roles.length) {
        values.roles.map((x) => {
          arr.push(x.value);
        });
      }

      if (employee) {
        handleEmployeesAction({
          action: "UpdateEmployee",
          employee_details: {
            id: employee.id,
            hire_date: values.hire_date,
            terminal_date: values.terminal_date,
            user: values.user.value,
            is_active: values.is_active,
            department: values.department ? values.department.value : null,
            designation: values.designation ? values.designation.value : null,
            advert: values.advert ? values.advert.value : null,
    
          },
        });
      } else {
        handleEmployeesAction({
          action: "CreateEmployee",
          employee_details: {
            hire_date: values.hire_date,
            terminal_date: values.terminal_date,
            user_id: values.user.value,
            is_active: values.is_active,
            department: values.department ? values.department.value : null,
            designation: values.designation ? values.designation.value : null,
            advert: values.advert ? values.advert.value : null,
            roles: arr,
     
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  //Retrieve designations
  const [designations, setDesignations] = useState([]);
  const designationsActionsApi = useApi(designationsApi.designationsAction);
  const getDesignations = async () => {
    await designationsActionsApi.request({
      action: "EntityDesignations",
    });
  };
  useEffect(() => {
    getDesignations();
  }, []);

  useEffect(() => {
    if (designationsActionsApi.data && designationsActionsApi.data.length) {
      setDesignations(
        designationsActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
    console.log("designationsActionsApi.data", designationsActionsApi.data);
  }, [designationsActionsApi.data]);

  //Retrieve roles

  const [roles, setRoles] = useState([]);
  const rolesActionsApi = useApi(rolesApi.rolesAction);
  const getRoles = async () => {
    await rolesActionsApi.request({
      action: "GetEntityRoles",
    });
  };
  useEffect(() => {
    getRoles();
  }, []);

  
  useEffect(() => {
  
    if (rolesActionsApi.data && rolesActionsApi.data.length) {
      setRoles(
        rolesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("roles", roles);
  }, [rolesActionsApi.data]);

  //Retrieve departments
  const [departments, setDepartments] = useState([]);
  const departmentsActionsApi = useApi(departmentsApi.departmentsAction);
  const getDepartments = async () => {
    await departmentsActionsApi.request({
      action: "GetEntityDepartments",
      entity: loggedInUser.entity_id,
    });
  };


  useEffect(() => {
    if (loggedInUser) {
      getDepartments();
    }
  }, [loggedInUser]);

  useEffect(() => {
    if (departmentsActionsApi.data && departmentsActionsApi.data.length) {
      setDepartments(
        departmentsActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("departmentsActionsApi.data", departmentsActionsApi.data);
  }, [departmentsActionsApi.data]);

  //Retrieve adverts
  const [adverts, setAdverts] = useState([]);
  const advertsActionsApi = useApi(advertsApi.advertsAction);
  const getAdverts = async () => {
    await advertsActionsApi.request({
      action: "GetAdverts",
    });
  };

  useEffect(() => {
    getAdverts();
  }, []);

  useEffect(() => {
    if (advertsActionsApi.data && advertsActionsApi.data.length) {
      setAdverts(
        advertsActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("adverts", adverts);
  }, [advertsActionsApi.data]);

  //Retrieve followers
  const [followers, setFollowers] = useState([]);
  const followersActionsApi = useApi(entitiesApi.entitiesActionAdmin);
  const getFollowers = async () => {
    await followersActionsApi.request({
      action: "GetEntityFollowers",
    });
  };

  useEffect(() => {
    if (followersActionsApi.data && followersActionsApi.data.length) {
      setFollowers(
        followersActionsApi.data.map((i) => ({ label: `${i.title} - ${i.phone}`, value: i.id }))
      );
    }

    console.log("followersActionsApi.data", followersActionsApi.data);
  }, [followersActionsApi.data]);

  const handleHireDateChange = (date, dateString) => {
    formik.setFieldValue("hire_date", dateString);
    console.log("HD", dateString);
  };

  const handleRetireDateChange = (date, dateString) => {
    formik.setFieldValue("terminal_date", dateString);
    console.log("DS", dateString);
  };

  useEffect(() => {
    getFollowers();
  }, []);

  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)



  };

    //Entity Users
    const searchUserApi = useApi(usersApi.usersAction);

    const searchUsers = async (data) => {
      await searchUserApi.request(data);
    };
    const [users, setUsers] = useState();
    const loadUserOptions = async (inputText = "", callback) => {
      searchUsers({
        action: "SearchUsers",
        searchQuery: inputText,
      });
      callback(users.map((i) => ({ label: `${i.title} - ${i.phone}`, value: i.id })));
    };
  
    useEffect(() => {
      if (searchUserApi.data) {
        if (searchUserApi.data.length) {
          setUsers(searchUserApi.data);
        }
      }
      console.log("searchManufacturerApi.data", searchUserApi.data);
    }, [searchUserApi.data]);

  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={modalTitle}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        {errors && errors.length ? (
          <div>
            {errors.map((x) => {
              return <p className="text-red-400 font-bold text-medium">{x}</p>;
            })}
          </div>
        ) : (
          <div></div>
        )}

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className="grid grid-cols-1 gap-2  items-center w-full my-7"
        >


        <CustomFormItem
        touched={formik.touched.user}
        error={formik.errors.user}
      >
        <CustomSelectAsyncSelect
          placeholder="Search  user by phone number"
          isClearable
          value={formik.values.user}
          onChange={(value) => formik.setFieldValue("user", value)}
          loadOptions={loadUserOptions}
        />
      </CustomFormItem>   

          <CustomFormItem
            touched={formik.touched.advert}
            error={formik.errors.advert}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="advert"
              id="advert"
              label="Select advert"
              size="large"
              onChange={(value) => formik.setFieldValue("advert", value)}
              value={formik.values.advert}
              placeholder="Select advert"
              options={adverts}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.designation}
            error={formik.errors.designation}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="designation"
              id="designation"
              label="Select designation"
              size="large"
              onChange={(value) => formik.setFieldValue("designation", value)}
              value={formik.values.designation}
              placeholder="Select designation"
              options={designations}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.department}
            error={formik.errors.department}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="department"
              id="department"
              label="Select department"
              size="large"
              onChange={(value) => formik.setFieldValue("department", value)}
              value={formik.values.department}
              placeholder="Select department"
              options={departments}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.roles}
            error={formik.errors.roles}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="roles"
              id="roles"
              label="Select roles"
              size="large"
              isMulti={true}
              onChange={(value) => formik.setFieldValue("roles", value)}
              value={formik.values.roles}
              placeholder="Select roles"
              options={roles}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.hire_date}
            error={formik.errors.hire_date}
          >
            <CustomDatePicker
              id="hire_date"
              name="hire_date"
              size="large"
              placeholder="Select hire date"
              onChange={handleHireDateChange}
              defaultValue={dayjs(formik.values.hire_date, "YYYY-MM-DD")}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.terminal_date}
            error={formik.errors.terminal_date}
          >
            <CustomDatePicker
              id="terminal_date"
              name="terminal_date"
              size="large"
              placeholder="Select terminal date"
              onChange={handleRetireDateChange}
              defaultValue={dayjs(formik.values.terminal_date, "YYYY-MM-DD")}
            />
          </CustomFormItem>


          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
            />
          </CustomFormItem>
          <div></div>

  

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
