import client from "./client";

const entitiesAction = (data) => {
   
    return client.post("/authentication/entities", data);

};
const entitiesActionAdmin = (data) => {
 
    return client.post("/authentication/entities/admin", data);

};

const plansActionAdmin = (data) => {
   
    return client.post("/authentication/plans", data);

};

export default {
    entitiesAction,
    entitiesActionAdmin,
    plansActionAdmin
};
