import React, { useEffect, useState } from 'react'
import RolesTable from './RolesTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import EmployeesFormModal from './EmployeesFormModal';
import employeesApi from '../../../api/employees/employeesApi';
import { Loading } from '../../../components';
import { useStateContext } from '../../../contexts/ContextProvider';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Department", uid: "department_title" },
    { name: "Designation", uid: "designation_title" },
    { name: "Added", uid: "hire_date" },
    { name: "Actions", uid: "actions" },
];


function DepartmentsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const { loggedInUser } = useStateContext()

    const navigate = useNavigate()
    const [employee, setEmployee] = useState()
    const [employees, setFEmployees] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const employeesActionsApi = useApi(employeesApi.employeesActionAdmin)

    const getEntityEmployees = async () => {
        await employeesActionsApi.request({
            "action": "RetrieveEntityEmployeesById",
            "entity": loggedInUser.entity_id

        })
    }


    useEffect(() => {
        getEntityEmployees()
        console.log("LIU", loggedInUser)
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setEmployee(item)
        setmodalTitle(`Edit ${item.title}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new employee")
        setEmployee(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (employeesActionsApi.data && employeesActionsApi.data.length) {

            setFEmployees(employeesActionsApi.data)
        }
        console.log("employeesActionsApi.data", employeesActionsApi.data)
    }, [employeesActionsApi.data])

    useEffect(() => {
        getEntityEmployees()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(employees)
    }, [employees])


    const handleFilter = (e) => {
        const search_param = e
        if (employees && employees.length > 0 && search_param && search_param !== '') {
            setdata(employees.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(employees);
        }

    };

    return employeesActionsApi.loading ? <Loading loading={employeesApi.loading} /> : (
        <div>
            {openEditModal && <EmployeesFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} employee={employee} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <RolesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DepartmentsList